# src/mapper.py# --- Fuzzy mapper (kept as fallback) ---from rapidfuzz import fuzzfrom .provider import complete_json, LLMUnavailable, availableALIASES = {    "tensile_strength": ["uts", "ultimate_tensile_strength", "tensile_strength_mpa", "σ_uts", "tensile strength"],    "elongation_at_break": ["elong%", "elongation", "eab", "elongation_at_break_%", "elongation at break"],    "modulus": ["youngs_modulus", "e_modulus", "modulus_gpa", "young's modulus", "E"],    "specimen_type": ["specimen", "sample_type", "type"],    "test_speed_mm_per_min": ["speed", "crosshead_speed", "mm_min", "test_speed"],    "lot": ["lot", "batch_id", "lot_id"],}def suggest_mapping_fuzzy(headers, required_metrics):    mapping = {}    for m in required_metrics:        best_h, best_s = None, -1        for h in headers:            scores = [fuzz.WRatio(h, m)] + [fuzz.WRatio(h, a) for a in ALIASES.get(m, [])]            s = max(scores)            if s > best_s:                best_h, best_s = h, s        mapping[m] = best_h    return mapping# --- LLM mapper ---def suggest_mapping_llm(headers, required_metrics):    """Map CSV headers to canonical metrics.    Returns {"mapping": {...}, "notes": "..."} or None if unavailable.    """    if not available():        return None    system = (        "Map CSV headers to canonical metrics. Return JSON only. "        "If unsure, choose the closest header. If no header fits, use an empty string."    )    user = f"""Required metrics: {required_metrics}Available headers: {headers}Return a JSON object with exactly two keys:"mapping" - an object pairing each required metric with the best header name"notes" - one short sentence explaining the choices"""    try:        obj = complete_json(system, user, max_tokens=300)    except LLMUnavailable:        return None    if not isinstance(obj, dict) or not isinstance(obj.get("mapping"), dict):        return None    return obj